import hashlib

def leaf_hash(data):
    return hashlib.sha256(b"\x00" + data).digest()

def node_hash(left, right):
    return hashlib.sha256(b"\x01" + left + right).digest()

def verify(data, index, size, proof, root):
    if not 0 <= index < size:
        return False
    h, rest = leaf_hash(data), list(proof)
    while size > 1:
        if index % 2 == 1:
            if not rest:
                return False
            h = node_hash(rest.pop(0), h)
        elif index + 1 < size:
            if not rest:
                return False
            h = node_hash(h, rest.pop(0))
        index, size = index // 2, (size + 1) // 2
    return not rest and h == root

