import hashlib

def H(b):
    return hashlib.sha256(b).digest()

def naive_root(leaves):
    level = [H(d) for d in leaves]
    while len(level) > 1:
        if len(level) % 2:
            level = level + [level[-1]]
        level = [H(level[i] + level[i + 1]) for i in range(0, len(level), 2)]
    return level[0]

def forge(leaves):
    """Return a list of byte strings, different from `leaves`, with the same naive_root."""
    return list(leaves)

