import hashlib

def H(b):
    return hashlib.sha256(b).digest()

def naive_root(leaves):
    level = [H(d) for d in leaves]
    while len(level) > 1:
        if len(level) % 2:
            level = level + [level[-1]]
        level = [H(level[i] + level[i + 1]) for i in range(0, len(level), 2)]
    return level[0]

def forge(leaves):
    hashes = [H(d) for d in leaves]
    if len(hashes) % 2:
        hashes.append(hashes[-1])
    return [hashes[i] + hashes[i + 1] for i in range(0, len(hashes), 2)]
